import { test } from '../../assert';

export default test({
	async test({ assert, target }) {
		const button = target.querySelector('button');
		button?.click();

		// wait for the transition's keyframes to be created
		const animation = await new Promise((resolve, reject) => {
			const start = performance.now();

			function check() {
				const outer = target.querySelector('.level-2');
				const animation = outer
					?.getAnimations()
					.find((a) => a.effect?.getTiming().duration === 100);

				if (animation) {
					resolve(animation);
				} else if (performance.now() - start > 2000) {
					reject(new Error('timed out waiting for the transition to start'));
				} else {
					requestAnimationFrame(check);
				}
			}

			check();
		});

		// the outermost `slide` must have measured the element with its
		// descendants at their natural size, not collapsed to zero by their
		// own starting styles (#18421)
		const keyframes = animation.effect?.getKeyframes() ?? [];
		assert.equal(keyframes[keyframes.length - 1].height, '100px');
	}
});

import { ok, test } from '../../assert';

export default test({
	async test({ assert, window }) {
		window.document.querySelector('button')?.click();
		await new Promise((r) => setTimeout(r, 100));

		const p = window.document.querySelector('p');
		const animations = /** @type {HTMLElement} */ (p).getAnimations();
		assert.equal(animations.length, 1);

		// when the element has no layout box, computed dimensions resolve to 'auto',
		// which must not end up as NaN values that the browser rejects (#14205)
		const effect = /** @type {KeyframeEffect} */ (animations[0].effect);
		const keyframes = effect.getKeyframes();
		ok(keyframes.length > 0);
		assert.equal(effect.getTiming().duration, 400);

		for (const keyframe of keyframes) {
			ok(!('height' in keyframe), 'unresolved height should be omitted');

			for (const value of Object.values(keyframe)) {
				ok(!String(value).includes('NaN'), `unexpected NaN in keyframe: ${value}`);
			}
		}
	}
});

