		p = parents['reactive_update'];
		assert.deepEqual(p.value, { foo: 'kid' });
		assert.equal(p.updates.length, 2);

		p = parents['reactive_mutate'];
		assert.deepEqual(p.value, { foo: 'kid' });
		assert.equal(p.updates.length, 2);

		p = parents['init_update'];
		assert.deepEqual(p.value, { foo: 'kid' });
		assert.equal(p.updates.length, 2);

		p = parents['init_mutate'];
		assert.deepEqual(p.value, { foo: 'kid' });
		assert.equal(p.updates.length, 2);
	}
});

