		component.tag = 'div';
		let divs = target.querySelectorAll('div');
		divs.forEach((div) => {
			div.getBoundingClientRect = function () {
				const index = [...(this.parentNode?.children ?? [])].indexOf(this);
				const top = index * 30;

				return /** @type {DOMRect} */ ({
					left: 0,
					right: 100,
					top,
					bottom: top + 20
				});
			};
