			<div id="f">FALSE</div>
		`
		);

		// toggling back in the middle of the out transition
		// will reuse the previous element
		await (component.condition = true);

		assert.htmlEqual(
			target.innerHTML,
			`
			<div id="t" foo="1">TRUE</div>
			<div id="f">FALSE</div>
		`
		);
		assert.equal(target.querySelector('#t'), t);

		raf.tick((time += 25));

		assert.htmlEqual(
			target.innerHTML,
			`
			<div id="t" foo="1">TRUE</div>
			<div id="f" foo="0.75">FALSE</div>
		`
		);

		raf.tick((time += 75));

		assert.htmlEqual(
			target.innerHTML,
			`
			<div id="t" foo="1">TRUE</div>
		`
		);
	}
});

