		// elements didn't clobber each other
		for (let n of ['1', '2', '3']) {
			const a = head.querySelector(`meta[name="a-${n}"]`);
			assert.equal(a?.getAttribute('content'), n);

			const b1 = head.querySelector(`meta[name="b-${n}-1"]`);
