		const input = target.querySelector('input');

		flushSync(() => {
			btn1?.click();
		});

		assert.htmlEqual(
			target.innerHTML,
			`<input type="checkbox"><button>x:
		 6,
		 y:
		 12</button><button>x:
		 2,
		 y:
		 4</button>`
		);

